# create-restaurant-kpis-poster-page.ps1
# ONE-SHOT SCRIPT: writes the corrected poster image (embedded, no download needed),
# creates restaurant-kpis-every-manager-should-track.html, and updates sitemap.xml.
# Run this from: C:\Users\admin\Desktop\nigelthomas-portfolio
# Usage: .\create-restaurant-kpis-poster-page.ps1

$ErrorActionPreference = "Stop"

# -----------------------------------------------------------------------
# STEP 1: Decode and write the corrected poster image to /assets/
# (Byline corrected to "By Nigel A. Thomas" — embedded as base64 so there
# is no browser-download / numbered-suffix issue.)
# -----------------------------------------------------------------------
$assetsDir = Join-Path (Get-Location) "assets"
if (-not (Test-Path $assetsDir)) {
    New-Item -ItemType Directory -Path $assetsDir | Out-Null
}
$imagePath = Join-Path $assetsDir "restaurant-kpis-every-manager-should-track.jfif"

$posterBase64 = @'

'@

$imageBytes = [Convert]::FromBase64String($posterBase64)
[System.IO.File]::WriteAllBytes($imagePath, $imageBytes)
Write-Host "Image written: $imagePath" -ForegroundColor Green

# -----------------------------------------------------------------------
# STEP 2: Create the poster blog page (matches your confirmed design
# system: #0b0b0b background, #d4af37 gold, Segoe UI/Arial, GA4, AdSense)
